import { expect, expectStatus, test } from "../../fixtures";

test("Signing out clears the session cookie", { tag: "@AUTH-06" }, async ({ apiAs }) => {
  // Arrange
  const member = await apiAs("member");

  // Act
  const response = await member.post("/api/auth/logout");

  // Assert
  await expectStatus(response, 204);
  const cookie = response.headersArray().find((h) => h.name.toLowerCase() === "set-cookie" && h.value.startsWith("session="));
  expect(cookie, "the response sets the session cookie").toBeDefined();
  const [pair, ...attributes] = (cookie?.value ?? "").split(";").map((part) => part.trim());
  // The value may be written bare (session=) or quoted (session=""); both are an empty cookie value.
  const value = pair.slice("session=".length).replace(/^"(.*)"$/, "$1");
  expect(value, `the session cookie value is empty: ${cookie?.value}`).toBe("");
  const expiresNow = attributes.some((a) => /^max-age=0$/i.test(a) || /^expires=.*1970/i.test(a));
  expect(expiresNow, `the session cookie expires immediately: ${cookie?.value}`).toBe(true);
});
